const std = @import("std");

const CacheEntry = struct {
    key: u32,
    value: u32,
};

pub fn main() !void {
    const capacity: usize = 3;
    var cache: [3]CacheEntry = undefined;
    var size: usize = 0;

    const ops = [_]u32{ 1, 2, 3, 4, 1, 2 };
    for (ops) |key| {
        var found = false;
        for (0..size) |i| {
            if (cache[i].key == key) {
                const val = cache[i].value;
                var j = i;
                while (j + 1 < size) { cache[j] = cache[j + 1]; j += 1; }
                cache[size - 1] = CacheEntry{ .key = key, .value = val };
                found = true;
                break;
            }
        }
        if (!found) {
            if (size < capacity) { size += 1; }
            var k: usize = 0;
            while (k + 1 < size) { cache[k] = cache[k + 1]; k += 1; }
            cache[size - 1] = CacheEntry{ .key = key, .value = key * 10 };
        }
    }

    for (0..size) |i| std.debug.print("{}:{}\n", .{cache[i].key, cache[i].value});
}
